        System.out.println("Long input is " + longInput);
        System.out.println("Float input is " + floatInput);
        System.out.println("Double input is " + doubleInput);
        System.out.println("Boolean input is " + booleanInput);
        System.out.println("Word input is " + wordInput);
        System.out.println("Full name is " + fullName);
        System.out.println("Character is " + character);
    }
}

import java.util.Scanner;

class Check {

    boolean checkDivisibility(int a, int b) {

        boolean result =

            b % 5 == 0;

        return result;
    }
}

class MainApp {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        System.out.println("Enter two numbers:");

        int a = scan.nextInt();
        int b = scan.nextInt();

        Check check = new Check();

        boolean finalResult =
            check.checkDivisibility(a, b);

        System.out.println(
            a + " and " + b +
            " are divisible by 5? " +
            finalResult
        );
    }
}

